\set ON_ERROR_STOP on
create function pg_temp.assert_true(ok boolean,label text) returns void language plpgsql as $$ begin if ok is not true then raise exception 'FAIL: %',label; end if; end $$;
create function pg_temp.expect_error(statement text,expected text,label text) returns void language plpgsql as $$ begin begin execute statement; exception when others then if sqlstate=expected then return; end if; raise exception 'FAIL: % expected %, received %',label,expected,sqlstate; end; raise exception 'FAIL: % unexpectedly allowed',label; end $$;
update public.profiles set is_active=true where id='10000000-0000-4000-8000-000000000002';
set role authenticated;
select set_config('request.jwt.claim.sub','10000000-0000-4000-8000-000000000001',false);
insert into public.contacts(id,first_name,last_name) values('30000000-0000-4000-8000-000000000002','Demo','Participant Two');
select public.save_activity(null,'{"organization_id":"20000000-0000-4000-8000-000000000001","occurred_at":"2020-01-01T14:30:00Z","activity_type":"Meeting","purpose":"Synthetic Check-in","location":"Demo Room","key_discussion":"Synthetic discussion","sponsor_needs":"Demo needs","cbc_opportunity":"Demo opportunity","outcome":"Demo outcome"}',array['30000000-0000-4000-8000-000000000001'::uuid,'30000000-0000-4000-8000-000000000002'::uuid]) as activity_id \gset
select pg_temp.assert_true((select count(*)=2 from public.activity_contacts where activity_id=:'activity_id'),'multiple participants persisted');
select pg_temp.assert_true((select key_discussion='Synthetic discussion' and outcome='Demo outcome' from public.activities where id=:'activity_id'),'manual fields persisted');
insert into public.tasks(id,activity_id,description,owner_id,due_date) values
('40000000-0000-4000-8000-000000000001',:'activity_id','Synthetic overdue','10000000-0000-4000-8000-000000000002',public.activity_today()-1),
('40000000-0000-4000-8000-000000000002',:'activity_id','Synthetic today','10000000-0000-4000-8000-000000000003',public.activity_today()),
('40000000-0000-4000-8000-000000000003',:'activity_id','Synthetic undated',null,null);
select pg_temp.assert_true((select status='Overdue' and owner_name='Demo Staff A' from public.follow_ups where id='40000000-0000-4000-8000-000000000001'),'derived overdue and permitted owner label');
select pg_temp.assert_true((select status='Open' from public.follow_ups where id='40000000-0000-4000-8000-000000000002'),'due today open');
select pg_temp.assert_true((select status='Open' from public.follow_ups where id='40000000-0000-4000-8000-000000000003'),'undated open');
select pg_temp.assert_true(public.follow_up_status('2026-07-01',null,'2026-07-01')='Open','fixed date boundary');
select pg_temp.assert_true(public.follow_up_status('2026-07-01',null,'2026-07-02')='Overdue','next calendar day overdue');
select pg_temp.assert_true(public.follow_up_status('2026-07-01','2026-07-01T00:00:00Z','2026-07-02')='Complete','completion precedence');
set timezone='Asia/Tokyo';
select pg_temp.assert_true(public.activity_today()=(statement_timestamp() at time zone 'America/Edmonton')::date,'calendar independent of session timezone');
set timezone='UTC';
update public.tasks set completed_at=now() where id='40000000-0000-4000-8000-000000000001';
select pg_temp.assert_true((select status='Complete' from public.follow_ups where id='40000000-0000-4000-8000-000000000001'),'completed overdue disappears');
update public.tasks set completed_at=null where id='40000000-0000-4000-8000-000000000001';
select pg_temp.assert_true((select status='Overdue' from public.follow_ups where id='40000000-0000-4000-8000-000000000001'),'reopened overdue');
select pg_temp.assert_true(public.activity_last_contact(p_organization_id=>'20000000-0000-4000-8000-000000000001')='2020-01-01T14:30:00Z','organization last contact');
select pg_temp.assert_true(public.activity_last_contact(p_contact_id=>'30000000-0000-4000-8000-000000000002')='2020-01-01T14:30:00Z','contact last contact');
select public.save_activity(null,'{"organization_id":"20000000-0000-4000-8000-000000000001","occurred_at":"2099-01-01T14:30:00Z","activity_type":"Meeting","purpose":"Planned meeting"}',array['30000000-0000-4000-8000-000000000002'::uuid]) as future_id \gset
select pg_temp.assert_true(public.activity_last_contact(p_activity_id=>:'future_id')='2020-01-01T14:30:00Z','future record excluded from last contact');
select pg_temp.expect_error(format($q$select public.save_activity(%L,'{"occurred_at":"2021-01-01T12:00Z","activity_type":"Call","purpose":"Must rollback"}',array['30000000-0000-4000-8000-000000000099'::uuid])$q$,:'activity_id'),'42501','invalid participant atomic rejection');
select pg_temp.assert_true((select purpose='Synthetic Check-in' from public.activities where id=:'activity_id'),'atomic activity rollback');
select pg_temp.assert_true((select count(*)=2 from public.activity_contacts where activity_id=:'activity_id'),'atomic participant rollback');
select pg_temp.expect_error($q$insert into public.activities(occurred_at,activity_type) values(now(),' ')$q$,'23514','nonblank activity type');
select pg_temp.expect_error($q$insert into public.activities(occurred_at,activity_type) values('infinity','Call')$q$,'23514','finite activity date');
select pg_temp.expect_error(format($q$insert into public.tasks(activity_id,description,due_date) values(%L,'Invalid','infinity')$q$,:'activity_id'),'23514','finite due date');
select pg_temp.expect_error($q$update public.tasks set owner_id='10000000-0000-4000-8000-000000000006'$q$,'23514','inactive action owner denied');
select pg_temp.expect_error($q$update public.tasks set owner_id='10000000-0000-4000-8000-000000000004'$q$,'23514','finance action owner denied');
select pg_temp.expect_error(format($q$update public.tasks set activity_id=%L where id='40000000-0000-4000-8000-000000000001'$q$,:'future_id'),'42501','action cannot be silently relinked');
select pg_temp.expect_error($q$update public.follow_ups set status='Complete'$q$,'55000','calculated status not writable');
select set_config('request.jwt.claim.sub','10000000-0000-4000-8000-000000000002',false);
select pg_temp.expect_error($q$update public.tasks set owner_id='10000000-0000-4000-8000-000000000003' where id='40000000-0000-4000-8000-000000000001'$q$,'23514','staff cannot choose hidden owner');
update public.tasks set description='Staff updated action' where id='40000000-0000-4000-8000-000000000002';
select pg_temp.assert_true((select owner_name is null from public.follow_ups where id='40000000-0000-4000-8000-000000000002'),'restricted owner label not disclosed');
select pg_temp.expect_error($q$update public.organizations set relationship_owner=null where id='20000000-0000-4000-8000-000000000001'$q$,'42501','ADR-010 ownership unchanged');
select set_config('request.jwt.claim.sub','10000000-0000-4000-8000-000000000004',false);
select pg_temp.assert_true((select count(*)=2 from public.activities),'finance reads activities');
with changed as (update public.tasks set description='Denied' returning id) select pg_temp.assert_true((select count(*)=0 from changed),'finance task edit denied');
select pg_temp.expect_error($q$select public.save_activity(null,'{"occurred_at":"2020-01-01","activity_type":"Call"}',array[]::uuid[])$q$,'42501','finance RPC denied');
select set_config('request.jwt.claim.sub','10000000-0000-4000-8000-000000000005',false);
select pg_temp.assert_true((select count(*)=3 from public.follow_ups),'viewer reads status view through RLS');
select pg_temp.expect_error(format($q$insert into public.tasks(activity_id,description) values(%L,'Denied')$q$,:'activity_id'),'42501','viewer task create denied');
select pg_temp.expect_error(format($q$insert into public.activity_contacts values(%L,'30000000-0000-4000-8000-000000000002')$q$,:'future_id'),'42501','viewer participant write denied');
reset role;
update public.profiles set is_active=false where id='10000000-0000-4000-8000-000000000003';
set role authenticated;
select set_config('request.jwt.claim.sub','10000000-0000-4000-8000-000000000001',false);
update public.tasks set description='Preserved historical owner' where id='40000000-0000-4000-8000-000000000002';
select pg_temp.assert_true((select owner_name is null from public.follow_ups where id='40000000-0000-4000-8000-000000000002'),'inactive directory label removed');
select set_config('request.jwt.claim.sub','10000000-0000-4000-8000-000000000006',false);
select pg_temp.assert_true((select count(*)=0 from public.activities),'inactive no activity reads');
select pg_temp.assert_true((select count(*)=0 from public.follow_ups),'security invoker view preserves inactive denial');
select pg_temp.assert_true(public.activity_last_contact(p_activity_id=>:'activity_id') is null,'last contact RPC cannot bypass RLS');
reset role;
set role anon;
select pg_temp.expect_error($q$select * from public.activities$q$,'42501','anonymous activities denied');
select pg_temp.expect_error($q$select * from public.follow_ups$q$,'42501','anonymous action view denied');
select pg_temp.expect_error($q$select public.activity_today()$q$,'42501','anonymous RPC denied');
reset role;
select pg_temp.assert_true((select reloptions @> array['security_invoker=true'] from pg_class where oid='public.follow_ups'::regclass),'follow ups view is invoker');
select pg_temp.assert_true((select count(*)=3 from pg_tables where schemaname='public' and tablename in ('activities','activity_contacts','tasks') and rowsecurity),'RLS enabled all new tables');
select pg_temp.assert_true(not has_function_privilege('authenticated','private.validate_task_owner()','execute'),'task trigger not RPC callable');
select pg_temp.assert_true((select proconfig @> array['search_path=""'] from pg_proc where oid='public.touch_updated_at()'::regprocedure),'timestamp helper search path pinned');
set role authenticated;
select set_config('request.jwt.claim.sub','10000000-0000-4000-8000-000000000001',false);
select public.save_activity(:'activity_id','{"organization_id":"20000000-0000-4000-8000-000000000001","occurred_at":"2020-01-01T14:30:00Z","activity_type":"Call","purpose":"Edited SQL activity","outcome":"Updated SQL outcome"}',array['30000000-0000-4000-8000-000000000002'::uuid]);
select pg_temp.assert_true((select outcome='Updated SQL outcome' and activity_type='Call' from public.activities where id=:'activity_id'),'positive atomic activity edit');
select pg_temp.assert_true((select count(*)=1 from public.activity_contacts where activity_id=:'activity_id'),'edit replaces participants');
select pg_temp.assert_true(public.activity_last_contact(p_contact_id=>'30000000-0000-4000-8000-000000000001') is null,'removed participant history no longer linked');
insert into public.tasks(id,activity_id,description,due_date) values('40000000-0000-4000-8000-000000000004',:'activity_id','Tie action',public.activity_today()-1);
select pg_temp.assert_true((select id='40000000-0000-4000-8000-000000000001' from public.follow_ups where completed_at is null order by due_date asc nulls last,id limit 1),'next action deterministic due-date tie');
select pg_temp.assert_true((select id='40000000-0000-4000-8000-000000000003' from public.follow_ups order by due_date desc nulls first,id limit 1),'undated action ordering');
select pg_temp.assert_true(('2026-03-09T05:59:59Z'::timestamptz at time zone 'America/Edmonton')::date='2026-03-08','Calgary midnight after DST before boundary');
select pg_temp.assert_true(('2026-03-09T06:00:00Z'::timestamptz at time zone 'America/Edmonton')::date='2026-03-09','Calgary midnight after DST boundary');
reset role;
select 'PASS activity CRUD, atomic participants, follow-up lifecycle, calendar, ownership and RLS assertions' as result;
